import * as THREE from 'https://cdn.jsdelivr.net/npm/three@0.161.0/build/three.module.js';

const canvas = document.querySelector('#game');
const scene = new THREE.Scene();
scene.background = new THREE.Color(0x687775);
scene.fog = new THREE.FogExp2(0x687775, 0.012);
const camera = new THREE.PerspectiveCamera(76, innerWidth / innerHeight, 0.08, 180);
camera.position.set(0, 1.68, 23);
const renderer = new THREE.WebGLRenderer({ canvas, antialias: true, powerPreference: 'high-performance' });
renderer.setPixelRatio(Math.min(devicePixelRatio, 1.7));
renderer.setSize(innerWidth, innerHeight);
renderer.shadowMap.enabled = true;
renderer.shadowMap.type = THREE.PCFSoftShadowMap;
renderer.outputColorSpace = THREE.SRGBColorSpace;
renderer.toneMapping = THREE.ACESFilmicToneMapping;
renderer.toneMappingExposure = 1.12;

const hemi = new THREE.HemisphereLight(0xc9d8d1, 0x34362f, 2.0);
scene.add(hemi);
const sun = new THREE.DirectionalLight(0xffe6c6, 3.2);
sun.position.set(-18, 30, 12); sun.castShadow = true;
sun.shadow.mapSize.set(2048, 2048);
sun.shadow.camera.left = -38; sun.shadow.camera.right = 38; sun.shadow.camera.top = 38; sun.shadow.camera.bottom = -38;
sun.shadow.bias = -0.0003; scene.add(sun);
const fill = new THREE.DirectionalLight(0x9bb8c7, 1.15); fill.position.set(18, 9, -18); scene.add(fill);

const materials = {};
function makeTexture(base, fleck, seed = 1) {
  const c = document.createElement('canvas'); c.width = c.height = 256;
  const ctx = c.getContext('2d'); ctx.fillStyle = base; ctx.fillRect(0, 0, 256, 256);
  let n = seed; const rand = () => { n = (n * 1664525 + 1013904223) >>> 0; return n / 4294967296; };
  for (let i=0;i<1800;i++) { const a=rand()*.16; ctx.fillStyle=`rgba(${fleck},${a})`; const x=rand()*256,y=rand()*256,s=rand()*3+0.4; ctx.fillRect(x,y,s,s); }
  for (let i=0;i<13;i++) { ctx.strokeStyle=`rgba(15,20,17,${rand()*.15})`; ctx.lineWidth=rand()*2+.3; ctx.beginPath(); const x=rand()*256,y=rand()*256; ctx.moveTo(x,y); ctx.lineTo(x+(rand()-.5)*70,y+rand()*55); ctx.stroke(); }
  const t = new THREE.CanvasTexture(c); t.wrapS=t.wrapT=THREE.RepeatWrapping; t.colorSpace=THREE.SRGBColorSpace; return t;
}
function mat(name,color,rough=.8,metal=0,texture=null){ return materials[name] ||= new THREE.MeshStandardMaterial({color,roughness:rough,metalness:metal,map:texture||null}); }
const concreteTex=makeTexture('#77776b','210,210,194',4); concreteTex.repeat.set(3,3);
const asphaltTex=makeTexture('#454a43','205,199,176',8); asphaltTex.repeat.set(8,8);
const rustTex=makeTexture('#695b46','229,190,137',2); rustTex.repeat.set(2,2);
const floorMat=mat('floor',0xffffff,.96,0,asphaltTex), wallMat=mat('wall',0xffffff,.95,0,concreteTex), rustMat=mat('rust',0xffffff,.78,.28,rustTex);
const darkMetal=mat('darkMetal',0x252b29,.43,.75), black=mat('black',0x131817,.38,.55), olive=mat('olive',0x424a3b,.8,.05), sand=mat('sand',0xb7aa8a,.93), cream=mat('cream',0xd1c4a0,.92), hazard=mat('hazard',0xc69b37,.78,.12), glass= new THREE.MeshStandardMaterial({color:0x263e43,metalness:.65,roughness:.2});
const colliders=[]; const mapObjects=[]; const bots=[]; const tracers=[]; const raycaster=new THREE.Raycaster();
function box(name,x,y,z,sx,sy,sz,material,collide=true,shadow=true){const m=new THREE.Mesh(new THREE.BoxGeometry(sx,sy,sz),material);m.name=name;m.position.set(x,y,z);m.castShadow=shadow;m.receiveShadow=true;scene.add(m);mapObjects.push(m);if(collide)colliders.push(m);return m;}
function cylinder(x,y,z,r1,r2,h,material,segments=12){const m=new THREE.Mesh(new THREE.CylinderGeometry(r1,r2,h,segments),material);m.position.set(x,y,z);m.castShadow=true;m.receiveShadow=true;scene.add(m);mapObjects.push(m);return m;}
function buildMap(){
  const floor=new THREE.Mesh(new THREE.PlaneGeometry(72,72),floorMat);floor.rotation.x=-Math.PI/2;floor.position.y=-.09;floor.receiveShadow=true;scene.add(floor);
  // Outer yard walls, with concrete panel seams and upper catwalks.
  box('North perimeter',0,3,-31,64,6,1.2,wallMat); box('South perimeter',0,3,31,64,6,1.2,wallMat);box('West perimeter',-31,3,0,1.2,6,62,wallMat);box('East perimeter',31,3,0,1.2,6,62,wallMat);
  for(let x=-27;x<=27;x+=9){box('wall seam',x,3,-30.34,.12,5.7,.04,mat('seam'+x,0x53594f),false,false);box('wall seam',x,3,30.34,.12,5.7,.04,mat('seams'+x,0x53594f),false,false);}
  // industrial sheds at back and side lanes
  box('Hangar rear',-19,4.2,-26,20,8.4,8,mat('hangar',0x55584c,.88),true);box('Hangar roof',-19,8.55,-26,21,0.5,9,mat('roof',0x363e3b,.68,.25),true);
  box('Hangar door',-19,2.4,-21.92,12,4.8,.12,mat('door',0x77796c,.82),false);
  for(let x=-24;x<=-14;x+=2)box('roll door ribs',x,2.4,-21.82,.055,4.5,.04,darkMetal,false,false);
  box('East warehouse',23,4,-21,12,8,16,mat('warehouse',0x6f6f60,.92),true);box('warehouse roof',23,8.1,-21,13,.4,17,mat('wr',0x3f4540,.55,.3),true);
  for(let x=19;x<=27;x+=2)box('warehouse panels',x,3.8,-12.95,.1,7.3,.09,darkMetal,false,false);
  // Container stacks provide distinct cover, with corrugated sides and markings.
  function container(x,z,color,w=9,h=3.1){const cm=mat('container'+x+z,color,.74,.38,rustTex);box('shipping container',x,h/2,z,w,h,3,cm,true);for(let xx=x-w/2+.24;xx<x+w/2;xx+=.48)box('container corrugation',xx,h/2,z+1.53,.065,h-.18,.06,darkMetal,false,false);box('container top rail',x,h-.11,z, w,.16,3.08,mat('rail',0x899083,.55,.5),false);box('container bottom rail',x,.13,z,w,.16,3.08,darkMetal,false);}
  container(-14,1,0x6b725d,10,3.3);container(12,9,0x786a4e,9,3.3);container(22,4,0x59665f,8,3.1);container(-22,13,0x76664e,8,3.1);container(7,-13,0x596459,9,3.2);container(-9,-16,0x7d694d,8,3.15);
  // concrete barriers, crates, drums
  const barricade=mat('barricade',0x77796d,.91);const crateMat=mat('crate',0x645b45,.92);
  [[0,0,6,1.25,2.5],[1,-7,4.5,1.35,2.1],[-3,9,5,1.2,2.1],[18,-6,3,1.1,2.2],[-18,-9,3.5,1.2,2.3],[6,21,5,1.2,2],[ -8,22,4,1.3,2.2]].forEach(([x,z,w,d,h])=>{const b=box('concrete barrier',x,h/2,z,w,h,d,barricade);box('barrier stripe',x,h*.72,z+d/2+.01,w*.7,.12,.02,hazard,false,false);});
  [[-5,-3],[-24,-1],[17,17],[2,-22],[-2,17],[26,-4],[14,-23]].forEach(([x,z],i)=>{const c=box('supply crate',x,.72,z,1.45,1.42,1.45,crateMat);c.rotation.y=(i%2)*.18;for(let j=-1;j<=1;j++)box('crate slat',x+j*.43,.73,z+.735,.08,1.3,.035,mat('slat'+i,0x342f25),false,false);});
  [[-27,5],[27,10],[5,26],[-6,-27],[19,2]].forEach(([x,z],i)=>{cylinder(x,.65,z,.42,.42,1.3,mat('drum'+i,i%2?0x464e49:0x76513a,.55,.55));cylinder(x,1.31,z,.43,.43,.08,darkMetal);});
  // Catwalks and gantry, visually framing the combat lane.
  box('catwalk west',-27,5.7,0,6,.22,29,darkMetal);box('catwalk east',27,5.7,-9,6,.22,16,darkMetal);
  for(let z=-13;z<=12;z+=3){box('rail west',-24,6.45,z,.12,1.4,.12,mat('rail2',0x555e58,.5,.5),false);box('rail west top',-24,7.15,z,.14,.12,.14,darkMetal,false);}
  for(let x=-30;x<=30;x+=6){box('roof truss',x,10,-29,.24,.3,4,darkMetal,false);}
  // Hazard markings on central lane
  const stripeMat=new THREE.MeshBasicMaterial({color:0xb69345});
  for(let x=-25;x<25;x+=4){const stripe=new THREE.Mesh(new THREE.PlaneGeometry(2,.12),stripeMat);stripe.rotation.x=-Math.PI/2;stripe.position.set(x,.005,0);scene.add(stripe);}
  // Pallets, pipes, cables and floodlights lend scale.
  for(let i=0;i<3;i++){const px=-28+i*3;box('pallet',px,.18,22,2.2,.35,1.5,crateMat);for(let k=-1;k<=1;k++)box('pallet board',px+k*.65,.38,22, .14,.12,1.5,olive,false);}
  for(let i=0;i<5;i++){const x=-30+i*15;box('light pole',x,7,0,.18,14,.18,darkMetal,false);box('light arm',x,13,-1,1.2,.12,.15,darkMetal,false);const l=new THREE.PointLight(0xffdca0,38,16,2);l.position.set(x,12.7,-1);scene.add(l);const bulb=new THREE.Mesh(new THREE.BoxGeometry(.8,.12,.35),new THREE.MeshBasicMaterial({color:0xffe1ad}));bulb.position.copy(l.position);scene.add(bulb);}
  // scatter broken brick and shell casings-like floor debris
  for(let i=0;i<65;i++){const x=(Math.random()-.5)*56,z=(Math.random()-.5)*55;const peb=new THREE.Mesh(new THREE.BoxGeometry(.12+Math.random()*.3,.035,.08+Math.random()*.18),i%3?mat('debris',0x656456):hazard);peb.position.set(x,.015,z);peb.rotation.y=Math.random()*3;peb.receiveShadow=true;scene.add(peb);}
  // Low barricade sandbags
  for(let i=0;i<3;i++){const m=new THREE.Mesh(new THREE.CapsuleGeometry(.38,.9,4,8),sand);m.rotation.z=Math.PI/2;m.position.set(9+i*.65,.42,19);m.castShadow=true;m.receiveShadow=true;scene.add(m);}
}
buildMap();

// First-person rifle: detailed receiver, handguard, optics, magazine and muzzle assembly.
const weapon=new THREE.Group();camera.add(weapon);scene.add(camera);weapon.position.set(.34,-.32,-.62);weapon.rotation.set(-.03,.02,-.025);
function weaponBox(parent,geo,material,x,y,z,rx=0,ry=0,rz=0){const m=new THREE.Mesh(geo,material);m.position.set(x,y,z);m.rotation.set(rx,ry,rz);m.castShadow=true;m.receiveShadow=true;parent.add(m);return m;}
weaponBox(weapon,new THREE.BoxGeometry(.17,.18,.5),black,0,0,0);
weaponBox(weapon,new THREE.BoxGeometry(.13,.12,.27),darkMetal,0,.05,-.16);
weaponBox(weapon,new THREE.BoxGeometry(.11,.15,.25),olive,0,-.16,.06,-.18);
weaponBox(weapon,new THREE.BoxGeometry(.09,.2,.1),black,0,-.18,.19,-.22);
weaponBox(weapon,new THREE.CylinderGeometry(.026,.026,.64,12),darkMetal,0,.015,-.48,Math.PI/2);
weaponBox(weapon,new THREE.CylinderGeometry(.045,.04,.07,12),black,0,.015,-.82,Math.PI/2);
weaponBox(weapon,new THREE.BoxGeometry(.055,.105,.17),olive,0,.06,-.43);
weaponBox(weapon,new THREE.BoxGeometry(.055,.085,.18),black,0,-.13,-.04,-.3);
weaponBox(weapon,new THREE.BoxGeometry(.06,.12,.08),darkMetal,0,.13,-.1);
weaponBox(weapon,new THREE.BoxGeometry(.07,.025,.21),black,0,.14,-.38);
weaponBox(weapon,new THREE.BoxGeometry(.045,.07,.07),darkMetal,0,.19,-.35);
weaponBox(weapon,new THREE.BoxGeometry(.04,.04,.12),mat('opticglass',0x1b2624,.25,.6),0,.19,-.35);
// front sight and underbarrel accessory
weaponBox(weapon,new THREE.BoxGeometry(.035,.09,.04),black,0,.13,-.7);
weaponBox(weapon,new THREE.BoxGeometry(.08,.07,.24),darkMetal,0,-.12,-.42);
const muzzleFlash=new THREE.PointLight(0xffb76a,0,4);muzzleFlash.position.set(0,.02,-.9);weapon.add(muzzleFlash);
const flashMesh=new THREE.Mesh(new THREE.ConeGeometry(.1,.34,8),new THREE.MeshBasicMaterial({color:0xffd38a,transparent:true,opacity:0}));flashMesh.rotation.x=-Math.PI/2;flashMesh.position.set(0,.02,-.97);weapon.add(flashMesh);

let playing=false,paused=false,gameOver=false,ads=false,shootHeld=false,fireCooldown=0,reloadTimer=0,matchTime=600,ammo=30,reserve=120,health=100,kills=0,deaths=0,shots=0,hits=0,blueScore=0,redScore=0,weaponKick=0,bob=0,sprint=false,lastTime=0,toastTimer=0;
const keys={};
const player={pos:new THREE.Vector3(0,0,23),yaw:Math.PI,pitch:0,velocity:new THREE.Vector3(),speed:5.2};
const spawnPoints=[[-25,22],[-23,-18],[-5,25],[22,22],[25,-18],[4,-25],[-15,5],[16,-3],[0,-12],[24,12]];
const teamColors={blue:0x4a8290,red:0x986252};
const hud={start:document.querySelector('#start-screen'),root:document.querySelector('#hud'),pause:document.querySelector('#pause-screen'),result:document.querySelector('#result-screen')};
function toast(msg){const t=document.querySelector('#toast');t.textContent=msg;t.classList.add('active');toastTimer=2.2;}

